style.css:
/* Apply to the body for the terminal background and text styling */
body {
    background-color: black !important;           /* Black background */
    color: #00FF00 !important;                    /* Green text color */
    font-family: 'Courier New', Courier, monospace !important;  /* Monospace font to give terminal feel */
    font-size: 18px !important;                   /* Slightly larger text for readability */
    line-height: 1.5 !important;                  /* Improve line spacing */
    margin: 0;
    padding: 20px;
    height: 100vh;                     /* Full screen height */
    overflow: hidden;                  /* Hide scrollbars */
}

/* Make links look like terminal links (optional) */
a {
    color: #00FF00;
    text-decoration: none;
    border-bottom: 1px solid #00FF00;
}

/* Add a cursor effect */
::after {
    content: '|';                    /* Simulate a cursor */
    animation: blink 0.7s step-end infinite;  /* Blink animation */
}

@keyframes blink {
    50% {
        opacity: 0;
    }
}

/* Optional: Styling for code blocks to look more like terminal input */
pre, code {
    background-color: black;
    color: #00FF00;
    font-family: 'Courier New', Courier, monospace;
    padding: 10px;
    border-radius: 5px;
    border: 1px solid #00FF00;
}
